import random
import re


_SMALL_CASES = (
    (2, "101"),
    (2, "0101"),
    (2, "1010"),
    (2, "10001"),
    (2, "10111"),
    (2, "11101"),
    (3, "1010101"),
    (4, "01010101"),
    (2, "01100110"),
)


def _format_input(k: int, s: str) -> str:
    return f"{len(s)} {k}\n{s}\n"


def _parse_input(inp: str) -> tuple[int, int, str] | None:
    lines = inp.splitlines()
    if len(lines) != 2:
        return None
    fields = lines[0].split()
    if len(fields) != 2:
        return None
    if any(re.fullmatch(r"[0-9]+", field) is None for field in fields):
        return None

    digits = [field.lstrip("0") or "0" for field in fields]
    if any(len(field) > 6 for field in digits):
        return None
    n, k = map(int, digits)
    s = lines[1].strip()
    if not (1 <= n <= 500_000 and 2 <= k <= (n + 1) // 2):
        return None
    if len(s) != n or re.fullmatch(r"[01]+", s) is None:
        return None
    if sum(1 for _ in re.finditer(r"1+", s)) < k:
        return None
    return n, k, s


def validate_input(inp: str) -> bool:
    return _parse_input(inp) is not None


def gen_small(seed: int, n: int) -> list[str]:
    rng = random.Random(seed)
    cases = [_format_input(k, s) for k, s in _SMALL_CASES[:max(0, n)]]
    while len(cases) < n:
        length = rng.randint(3, 8)
        s = "".join(rng.choice("01") for _ in range(length))
        blocks = len(re.findall(r"1+", s))
        if blocks >= 2:
            cases.append(_format_input(rng.randint(2, blocks), s))
    return cases


def gen_stress(seed: int) -> list[str]:
    rng = random.Random(seed)
    alternating = _format_input(250_000, "10" * 250_000)

    earlier_blocks = 70_000
    prefix = "0" * rng.randrange(129) + "10" * earlier_blocks
    previous = "1" * rng.randint(20_000, 22_000)
    moved = "1" * rng.randint(120_000, 130_000)
    suffix = "001" * 20_000
    gap_length = 500_000 - len(prefix + previous + moved + suffix)
    mixed = prefix + previous + "0" * gap_length + moved + suffix
    return [alternating, _format_input(earlier_blocks + 2, mixed)]


def check_postconditions(inp: str, out: str) -> list[tuple[str, str]]:
    parsed = _parse_input(inp)
    if parsed is None:
        return [("POST-1", "Input fails the stated preconditions.")]
    n, k, s = parsed

    tokens = out.split()
    if len(tokens) != 1 or re.fullmatch(r"[01]+", tokens[0]) is None:
        return [("POST-2", "Expected one binary string.")]
    t = tokens[0]
    if len(t) != n:
        return [("POST-2", f"Expected length {n}, found {len(t)}.")]

    failures = []
    previous_end = 0
    moved_end = 0
    input_blocks = 0
    for input_blocks, block in enumerate(re.finditer(r"1+", s), start=1):
        if input_blocks == k - 1:
            previous_end = block.end()
        if input_blocks == k:
            moved_end = block.end()

    if t[:previous_end] != s[:previous_end]:
        failures.append(("POST-3", "The prefix through block K−1 changed."))
    if t[moved_end:] != s[moved_end:]:
        failures.append(("POST-3", "The suffix after block K changed."))
    if t[previous_end] != "1" or t[moved_end - 1] != "0":
        failures.append(("POST-3", "The affected interval must start with 1 and end with 0."))

    if t.count("1") != s.count("1"):
        failures.append(("POST-4", "The number of 1 characters changed."))
    output_blocks = sum(1 for _ in re.finditer(r"1+", t))
    if output_blocks != input_blocks - 1:
        failures.append(("POST-4", "Expected exactly one fewer 1-block."))
    return failures


def metamorphic_pairs(seed: int, n: int) -> list[tuple[str, str, str, str]]:
    rng = random.Random(seed)
    pairs = []
    for _ in range(n):
        earlier_blocks = rng.randrange(4)
        prefix = "0" * rng.randrange(4) + "10" * earlier_blocks
        suffix = rng.choice(("", "0", "001", "01010", "00111"))
        gap = "0" * rng.randint(1, 6)
        total_ones = rng.randint(3, 12)
        first_split = rng.randint(1, total_ones - 1)
        second_split = rng.randint(1, total_ones - 2)
        if second_split >= first_split:
            second_split += 1

        # Redistribute ones between the two blocks while preserving their sum.
        first = prefix + "1" * first_split + gap + "1" * (total_ones - first_split) + suffix
        second = prefix + "1" * second_split + gap + "1" * (total_ones - second_split) + suffix
        k = earlier_blocks + 2
        pairs.append(("POST-3", "equal", _format_input(k, first), _format_input(k, second)))
    return pairs


def reference_small(inp: str) -> str | None:
    parsed = _parse_input(inp)
    if parsed is None:
        return None
    n, k, s = parsed
    if n > 12:
        return None

    blocks = []
    for left in range(n):
        for right in range(left, n):
            if any(s[i] != "1" for i in range(left, right + 1)):
                continue
            if left > 0 and s[left - 1] != "0":
                continue
            if right + 1 < n and s[right + 1] != "0":
                continue
            blocks.append((left, right))

    _, previous_end = blocks[k - 2]
    moved_start, moved_end = blocks[k - 1]
    moved_length = moved_end - moved_start + 1

    result = []
    for i in range(n):
        if i <= previous_end or i > moved_end:
            result.append(s[i])
        elif i <= previous_end + moved_length:
            result.append("1")
        else:
            result.append("0")
    return "".join(result) + "\n"
